UPDATE curated_question_catalog SET content_status='active',verified_at=now(),law_version_checked_at=CASE WHEN subject='Direito Penal' THEN now() ELSE law_version_checked_at END,legal_basis=CASE WHEN subject='Direito Penal' THEN '[{"title":"Código Penal (Decreto-Lei 2.848/1940), arts. 312 e 329-330","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}]'::jsonb ELSE legal_basis END,didactic_provenance=coalesce(didactic_provenance,'{}'::jsonb)||'{"editorial_review_status":"approved_on_merits","answer_type":"independently_reviewed_not_official_key","official_answer_verified":false,"trainer_release_blocked":false,"editorial_review_date":"2026-11-21","review_note":"Liberada com resposta juridica ou gramatical revisada; não rotular como gabarito oficial da banca."}'::jsonb WHERE external_item_key LIKE 'user-capture-20261121-%' AND external_item_key<>'user-capture-20261121-portugues-rogo-lhe-servir-nos' AND content_status='under_review' AND NOT EXISTS (SELECT 1 FROM curated_question_catalog other WHERE other.id<>curated_question_catalog.id AND other.content_status='active' AND regexp_replace(lower(other.question_text),'\s+','','g')=regexp_replace(lower(curated_question_catalog.question_text),'\s+','','g'));